// Config plugin: keeps the app data out of Android backups and device-to-device transfer (RF-088,
// E-028). The native settings live here, versioned, because android/ is generated by `prebuild`
// and never edited by hand. The iOS part arrives with T026.
const {
  AndroidConfig,
  withAndroidManifest,
  withDangerousMod,
} = require("expo/config-plugins");
const { mkdirSync, writeFileSync } = require("node:fs");
const { join } = require("node:path");

// Every backup domain of Android. Listing them all means a new Android version cannot add one
// that slips through: an empty or partial rule file means "back up everything else".
const DOMAINS = [
  "root",
  "file",
  "database",
  "sharedpref",
  "external",
  "device_root",
  "device_file",
  "device_database",
  "device_sharedpref",
];

const XML_FOLDER = "app/src/main/res/xml";
const RULES_NAME = "data_extraction_rules";
const FULL_BACKUP_NAME = "full_backup_content";

const excludes = (indent) =>
  DOMAINS.map(
    (domain) => `${indent}<exclude domain="${domain}" path="."/>\n`,
  ).join("");

// Android 12 and later. A missing <device-transfer> section would mean "transfer everything", even
// with allowBackup="false", so both sections are written.
const dataExtractionRules = () =>
  '<?xml version="1.0" encoding="utf-8"?>\n' +
  "<data-extraction-rules>\n" +
  `  <cloud-backup>\n${excludes("    ")}  </cloud-backup>\n` +
  `  <device-transfer>\n${excludes("    ")}  </device-transfer>\n` +
  "</data-extraction-rules>\n";

// Android 11 and lower ignore the file above and read this one.
const fullBackupContent = () =>
  '<?xml version="1.0" encoding="utf-8"?>\n' +
  `<full-backup-content>\n${excludes("  ")}</full-backup-content>\n`;

// Files are overwritten, not merged, so running prebuild again gives the same output and a stale
// file from an earlier run cannot leave an old rule behind.
function withBackupRuleFiles(config) {
  return withDangerousMod(config, [
    "android",
    (modConfig) => {
      const folder = join(modConfig.modRequest.platformProjectRoot, XML_FOLDER);
      mkdirSync(folder, { recursive: true });
      writeFileSync(join(folder, `${RULES_NAME}.xml`), dataExtractionRules());
      writeFileSync(
        join(folder, `${FULL_BACKUP_NAME}.xml`),
        fullBackupContent(),
      );
      return modConfig;
    },
  ]);
}

// Assigning the attributes replaces any value another plugin set, so there is one of each, ours.
function withBackupAttributes(config) {
  return withAndroidManifest(config, (modConfig) => {
    const application = AndroidConfig.Manifest.getMainApplicationOrThrow(
      modConfig.modResults,
    );
    application.$["android:dataExtractionRules"] = `@xml/${RULES_NAME}`;
    application.$["android:fullBackupContent"] = `@xml/${FULL_BACKUP_NAME}`;
    return modConfig;
  });
}

module.exports = function withBackupExclusion(config) {
  return withBackupAttributes(withBackupRuleFiles(config));
};
